def grid_min_path(cost: list[list[int]]) -> int:
    rows: int = len(cost)
    cols: int = len(cost[0])
    # copy cost into acc
    acc: list[list[int]] = []
    r_idx: int = 0
    while r_idx < rows:
        row_copy: list[int] = []
        c_idx: int = 0
        while c_idx < cols:
            row_copy.append(cost[r_idx][c_idx])
            c_idx = c_idx + 1
        acc.append(row_copy)
        r_idx = r_idx + 1

    r: int = 0
    while r < rows:
        c: int = 0
        while c < cols:
            if not (r == 0 and c == 0):
                # compute up
                if r > 0:
                    up: int = acc[r - 1][c]
                else:
                    up = 1000000000
                # compute left
                if c > 0:
                    left: int = acc[r][c - 1]
                else:
                    left = 1000000000
                # compute diag
                if r > 0 and c > 0:
                    diag: int = acc[r - 1][c - 1]
                else:
                    diag = 1000000000
                # find minimum of up, left, diag
                min_val: int = up
                if left < min_val:
                    min_val = left
                if diag < min_val:
                    min_val = diag
                acc[r][c] = acc[r][c] + min_val
            c = c + 1
        r = r + 1

    return acc[rows - 1][cols - 1]

